// Normaliza os dados que a IA mandou, de forma defensiva.
const inp   = (() => {
  const t = (() => { try { return $('Recebe da IA (Renovação)').first().json; } catch(e){ return null; } })();
  if (t && t.bid_id !== undefined) return t;           // veio do trigger (produção OU pin no trigger)
  const i = (() => { try { return $input.first().json; } catch(e){ return null; } })();
  if (i && i.bid_id !== undefined) return i;            // veio direto no nó (pin no Normaliza)
  return t || i || {};                                  // último recurso
})();
const cfg   = $('Configuracao').first().json;

// --- token: aceita com ou sem "Bearer", sempre devolve limpo e com "Bearer " uma vez
const rawToken = (inp.token || '').toString().trim();
const tokenLimpo = rawToken.replace(/^Bearer\s*/i, '').trim();      // sem prefixo
const authHeader = tokenLimpo ? ('Bearer ' + tokenLimpo) : '';      // com 1 prefixo

// --- bid_id obrigatório e numérico
const bidId = Number(inp.bid_id);
const bidValido = Number.isInteger(bidId) && bidId > 0;

// --- validade: default 30; só aceita 7/15/30
let validade = Number(inp.validade);
if (![7, 15, 30].includes(validade)) validade = 30;

return [{
  json: {
    base_url:   cfg.base_url,
    authKey:    cfg.authKey,
    bid_id:     bidId,
    bid_valido: bidValido,
    token_limpo: tokenLimpo,
    auth_header: authHeader,
    validade:   validade,
    period_hour: validade * 24,          // ex.: 720 para 30 dias
    email:      (inp.email || '').toString().trim(),
    phone_number: (inp.phone_number || '').toString().trim(),
  }
}];

// Clona o anúncio original: reaproveita TODOS os objetos, troca só a duração.
// Mapeamento confirmado contra o retorno real de GET /public/resources/bid/{id}.
const raw  = $('Busca Anúncio Original').first().json;
const orig = raw.data ?? raw;                 // a API devolve o objeto direto
const norm = $('Normaliza Entrada').first().json;

// helper: usa o valor do original; se nulo/ausente, cai no default
const val = (v, def) => (v !== undefined && v !== null ? v : def);

// duração = nova validade em horas (ex.: 30 dias -> "720:00")
const duration = norm.period_hour + ":00";

// validação mínima: sem produto/quantidade não dá pra recriar fiel
const faltando = [];
if (orig.product == null)  faltando.push('produto');
if (orig.quantity == null) faltando.push('quantidade');

const payload = {
  marketId:          val(orig.marketId, 1),
  operationId:       val(orig.operationId, 2),      // 1=compra 2=venda
  typeId:            val(orig.typeId, 2),
  product:           orig.product,                  // objeto completo
  visibilityId:      val(orig.visibilityId, 2),
  currencyId:        val(orig.currencyId, 1),
  price:             val(orig.price, 0),
  priceUnit:         orig.priceUnit,                // objeto completo
  quantity:          orig.quantity,
  quantityUnit:      orig.quantityUnit,             // objeto completo
  pickUp:            orig.pickUp,                   // objeto completo (cidade+estado)
  pickUpDescription: val(orig.pickUpDescription, null),
  logistics:         orig.logistics,               // objeto completo
  note:              val(orig.note, null),
  urlYouTube:        val(orig.urlYouTube, null),
  areaId:            val(orig.areaId, 1),
  duration:          duration,
  files:             []
};

return [{
  json: {
    payload,
    faltando,
    bid_id_original: norm.bid_id,
    auth_header: norm.auth_header,
    base_url: norm.base_url,
    validade: norm.validade
  }
}];

// Contrato de saída idêntico ao subworkflow de criação: status/anuncio_id/link
const item = $('Cria Anúncio Renovado').first().json;
const raw  = (typeof item === 'object' && item !== null)
  ? (item.data ?? item.id ?? item.body ?? null)
  : item;
const id = Number(raw);
if (id) {
  return [{ json: {
    status: "SUCESSO",
    anuncio_id: id,
    bid_id_original: $('Monta Clone').first().json.bid_id_original,
    validade: $('Monta Clone').first().json.validade,
    link: "https://agronegociar.com.br/detail/" + id
  }}];
}
return [{ json: {
  status: "ERRO",
  mensagem: "A API não retornou o ID do anúncio renovado. O anúncio NÃO foi criado. NÃO confirme a renovação ao cliente.",
  retorno_api: raw
}}];

